export const overviewJs="'use strict';\nconst $=id=>document.getElementById(id),money=n=>Number.isFinite(n)?n.toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2}):'—',node=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=String(text);if(cls)e.className=cls;return e;};\nlet data=null,selection=null,inFlight=false,controller=null,serial=0,dirty=false;\nconst query=new URLSearchParams(location.search);if(query.has('from')||query.has('to'))selection={from:query.get('from')??query.get('to'),to:query.get('to')??query.get('from')};\nfunction setMetric(id,value){const el=$(id);el.textContent=Number.isFinite(value)?'₹ '+money(value):'—';el.className=Number.isFinite(value)?value>0?'green':value<0?'red':'':'';}\nfunction render(){window.NseDates?.setSessions(data.availableSessions);const s=data.summary;setMetric('net',s.netPnl);setMetric('gross',s.grossPnl);$('fees').textContent='₹ '+money(s.costs.fees);$('slippage').textContent='₹ '+money(s.costs.slippage);$('buy').textContent='INR '+money(s.buyTurnover);$('sell').textContent='INR '+money(s.sellTurnover);\n $('net-label').textContent=s.complete?'COMBINED ESTIMATED NET':'KNOWN NET SUBTOTAL';$('net-detail').textContent='Closed '+money(s.realizedNet)+' · Open '+money(s.unrealizedNet)+(s.unresolvedCosts?' − '+money(s.unresolvedCosts)+' unresolved-position costs':'');$('gross-detail').textContent=s.valued+' / '+s.entries+' positions valued';$('fees-detail').textContent=s.missingCosts?s.missingCosts+' positions missing a complete cost estimate':'Brokerage + exchange + statutory charges';$('coverage-chip').textContent=!s.entries?'NO ENTERED TRADES':s.complete?'COMPLETE VALUED COVERAGE':data.errors.length?'PARTIAL · SOURCE READ ERROR':'PARTIAL · '+s.unresolved+' UNRESOLVED';$('coverage-chip').className='chip '+(s.entries&&!s.complete?'amber':'');\n $('period').textContent='Viewing '+data.selection.from+(data.selection.to!==data.selection.from?' → '+data.selection.to:'')+' IST · '+data.recordedSessionsInRange.length+' recorded '+(data.recordedSessionsInRange.length===1?'session':'sessions')+' · trade entry date';$('trade-count').textContent=s.entries+' POSITIONS · '+s.open+' OPEN · '+s.closed+' CLOSED';\n const warnings=[...data.errors];if(s.unresolved)warnings.push(s.unresolved+' positions have unresolved P&L or missing costs. Their missing P&L is excluded, not a known zero. The full combined result is incomplete.');if(s.unresolvedCosts)warnings.push('Known net deducts all known costs, including INR '+money(s.unresolvedCosts)+' on unresolved positions.');if(s.estimatedCosts)warnings.push(s.estimatedCosts+' positions use an estimated legacy cost breakdown; saved records were not modified.');if(s.estimatedOpenExitCosts)warnings.push('Open positions include INR '+money(s.estimatedOpenExitCosts)+' estimated round-trip costs at current marks, including hypothetical exit costs.');if(!data.recordedSessionsInRange.length)warnings.push('No recorded session exists in this date range. No historical price or trade is fabricated.');$('notice').hidden=!warnings.length;$('notice').textContent=warnings.join(' ');\n const body=$('strategy-rows');body.replaceChildren();for(const g of data.strategies.filter(g=>g.entries)){\n  const row=node('tr'),name=node('td');name.append(node('strong',g.name),node('small',g.id));if(g.estimatedCosts)name.append(node('small',g.estimatedCosts+' legacy cost estimates'));if(!g.complete)name.append(node('small','PARTIAL · '+g.unresolved+' unresolved','amber'));row.append(name);\n  const valueCell=key=>{const v=key==='fees'?g.costs.fees:key==='slippage'?g.costs.slippage:g[key];return node('td',money(v),key==='netPnl'?'net-value '+(v>0?'green':v<0?'red':''):'');};\n  row.append(valueCell('netPnl'),valueCell('fees'));const trades=node('td',g.entries);trades.append(node('small',g.closed+' closed · '+g.open+' open'));row.append(trades,valueCell('grossPnl'),valueCell('slippage'));row.append(node('td',g.wins+' / '+g.losses));const coverage=node('td');coverage.append(node('span',g.complete?'VALUED':'PARTIAL','coverage-tag '+(g.complete?'':'partial')),node('small',g.valued+'/'+g.entries+' valued'));row.append(coverage);body.append(row);\n }\n if(!body.children.length){const row=node('tr'),td=node('td','No entered paper trades recorded for this period.','empty-overview');td.colSpan=8;row.append(td);body.append(row);}\n const inactive=data.strategies.filter(g=>!g.entries);$('inactive').hidden=!inactive.length;$('inactive-summary').textContent=inactive.length+' strategies with no entered trades in this period';$('inactive-list').replaceChildren(...inactive.map(g=>node('span',g.name)));\n const costs=[['brokerage','Brokerage','Buy + sell orders'],['exchange','Exchange transaction charges','NSE / MCX, as modelled'],['transactionTax','STT / CTT','Transaction tax'],['gst','GST','On applicable charges'],['stamp','Stamp duty','Buy-side turnover'],['sebi','SEBI turnover fees',''],['ipft','IPFT / other modelled fees',''],['fees','Fees & taxes subtotal','Excludes assumed slippage'],['slippage','Assumed slippage','Separate execution assumption'],['total','Total estimated trading drag','Fees + taxes + slippage']];$('cost-breakdown').replaceChildren(...costs.map(([key,label,detail])=>{const r=node('div',undefined,['fees','total'].includes(key)?'cost-total':''),dt=node('dt',label),dd=node('dd',money(s.costs[key]));if(detail)dt.append(node('small',detail));r.append(dt,dd);return r;}));\n $('accounting').replaceChildren(node('div',s.savedCosts+' saved paper cost breakdowns'),node('div',s.estimatedCosts+' legacy breakdowns estimated from recorded fills'),node('div',s.missingCosts+' positions without a complete cost estimate'),node('div',s.unresolved+' unresolved outcomes / valuations'));$('updated').textContent='Updated '+new Date(data.servedAt).toLocaleTimeString('en-GB',{timeZone:'Asia/Kolkata',hour12:false})+' IST';$('connection').textContent='Refreshes every 10s · paper only';\n if(!dirty){$('from').value=data.selection.from;$('to').value=data.selection.to;}$('from').max=data.today;$('to').max=data.today;\n}\nasync function refresh(force=false){if(inFlight&&!force)return;controller?.abort();controller=new AbortController();const requestController=controller,active=++serial;inFlight=true;$('refresh').disabled=true;const timeout=setTimeout(()=>requestController.abort(),15000);try{const params=selection?'?'+new URLSearchParams(selection):'',r=await fetch('/api/overview'+params,{cache:'no-store',credentials:'same-origin',signal:requestController.signal});const next=await r.json();if(!r.ok)throw Error(next.error??'Overview unavailable');if(active!==serial)return;if(!next.paperOnly)throw Error('Unexpected data source');data=next;render();}catch(e){if(active===serial){$('connection').textContent='Disconnected · retrying automatically';$('notice').hidden=false;$('notice').textContent=(e.name==='AbortError'?'Request timed out':e.message)+'. Displayed results may be stale.';}}finally{clearTimeout(timeout);if(active===serial){inFlight=false;$('refresh').disabled=false;}}}\nfunction apply(from,to){if(!from||!to||from>to){$('notice').hidden=false;$('notice').textContent='Choose valid dates, with From before Through.';return;}dirty=false;selection={from,to};$('from').value=from;$('to').value=to;history.replaceState(null,'','/overview?'+new URLSearchParams(selection));refresh(true);}\n$('date-form').onsubmit=e=>{e.preventDefault();apply($('from').value,$('to').value);};$('from').oninput=$('to').oninput=()=>{dirty=true;};$('today').onclick=()=>data&&apply(data.today,data.today);$('latest').onclick=()=>data&&apply(data.availableSessions[0]??data.today,data.availableSessions[0]??data.today);$('all').onclick=()=>data&&apply(data.availableSessions.at(-1)??data.today,data.availableSessions[0]??data.today);$('refresh').onclick=()=>refresh(true);refresh();setInterval(()=>refresh(),10000);\n";
