export const charcoalCss="/* Shared deep black surfaces; trading colours are reserved for actual financial meaning. */\n:root{color-scheme:dark;--bg:#000000;--panel:#000000;--line:#333333;--muted:#b5b5b5;--text:#f2f2f2;--cyan:#e2e2e2;--green:#83d7a5;--red:#ff8b9c;--amber:#e9c582}\nhtml,body{background:#000000;color:var(--text)}.rail,header{background:#000000;border-color:#303030}.panel,.metrics article,.metric-grid article,.overview-metrics article,.compare-metrics article,.positions-summary article,.capital-metrics article,.daily-card{background:#000000;background-image:none;border-color:#333333;box-shadow:none;backdrop-filter:none}.shell{background:#000000}.rail .rail-icon{color:#b9b9b9}.rail .rail-icon.active{color:#fafafa;background:#000000;border-color:#404040}.rail .rail-icon:hover{color:#fff;background:#000000}.brand,.mark,.mark span{color:#f4f4f4}.eyebrow,.muted,small,.panel-body small,.agent-hero p,.scope-note,.period,.compare-hero p,.positions-intro,.positions-policy{color:#b5b5b5}.panel-head,.panel-foot,th{border-color:#333333}.panel-head,.table-scroll thead,.agent-page .table-scroll:has(#decisions) thead,.agent-page .table-scroll:has(#shadows) thead{background:#000000}th{color:#bdbdbd}td{border-color:#2c2c2c}.comparison tbody tr:hover,.position-group tr:hover{background:#000000}.selected-row,.position-group tr.is-open{background:#000000}.matrix th:first-child,.matrix td:first-child{background:#000000}.metric-grid strong,.capital-metrics strong,.compare-metrics strong,.positions-summary article:first-child strong{color:#f3f3f3}.agent-page .metric-grid strong.positive,.green,.positive{color:#83d7a5}.agent-page .metric-grid strong.negative,.red,.negative{color:#ff8b9c}.strategy-button,.stock-chart-link,.audit a,.methodology a,.strategy-manage,.lab-report-link,.session-review-link,.agent-page summary{color:#e6e6e6}.limits b{background:#000000;border-color:#565656;color:#ddd}.chip,.paper-label,.badge,.position-status,.coverage-tag{background:#000000;border-color:#606060;color:#dedede}.badge.approve,.coverage-tag:not(.partial){color:#a4d6b7}.badge.wait,.coverage-tag.partial{color:#e9c582}.badge.skip,.position-status.unknown{color:#ffabb6}.sort-buttons button[aria-pressed=true],.date-bar .apply,.select-trigger[aria-expanded=true],.select-option[aria-selected=true]{background:#000000;color:#fff;border-color:#8b8b8b}.select-menu{background:#000000;border-color:#686868;box-shadow:0 8px 20px #0005}.select-trigger,button,input,select{background:#000000;border-color:#404040;color:#ededed}.select-option{background:transparent}.select-option:hover,.select-option:focus{background:#000000}.select-trigger:after{border-color:#bbb}.date-bar,.strategy-switcher,#accounting,.shadow-summary>div,.audit pre,.agent-page pre{background:#000000;border-color:#343434;color:#c9c9c9}.capital-charts svg,.trade-svg-wrap svg{background:#000000}.methodology,.panel-foot,.panel-body.muted{color:#b5b5b5}.overview-metrics .net-card{background:#000000;border-color:#444444}.overview-metrics label,.overview-metrics small,.metric-grid label,.metric-grid small,.compare-metrics small,.capital-metrics small,.capital-charts figcaption{color:#bdbdbd}#cost-breakdown>div{border-color:#333333;color:#ccc}#cost-breakdown dt small,.comparison td small,.position-group .group-id{color:#aaa}.health,.ticker{background:#000000;border-color:#4c4c4c}.chart-wrap{background:#000000}.chart-wrap:before{background:none}.overview-notice,#notice,#error{background:#000000;border-color:#7e6a50;color:#eed3a8}.date-control button{background:transparent}.date-control button:hover{background:#000000}.date-popup button{background:transparent}.date-popup button:hover:not(:disabled){background:#000000}.date-popup .date-day[aria-selected=true]{background:#eee;color:#222}button:hover{border-color:#aaa}.date-control .date-arrow:disabled{color:#777}.comparison-page .chart-pad{background:#000000}\n/* Pitch-black chrome and the generated market-signal brand mark. */\n.rail .brand{display:flex;align-items:center;justify-content:center;gap:1px;width:100%;margin:0 0 24px;text-decoration:none}.brand-image{display:block;object-fit:contain;flex-shrink:0}.brand-wordmark{display:block;color:#fff;font:750 17px/1.1 system-ui;letter-spacing:1px}.brand-wordmark span{display:block;font:500 8px/1.8 ui-monospace,monospace;letter-spacing:2px;color:#bdbdbd}.backtest-brand{display:flex;align-items:center;flex-shrink:0}.rail .rail-icon.active{border-color:#606060;box-shadow:inset 2px 0 0 #eaeaea}.panel,.metric-grid article,.overview-metrics article,.compare-metrics article,.positions-summary article,.capital-metrics article,.daily-card{border-color:#242424}.panel-head,.panel-foot,td,th{border-color:#242424}@media(max-width:700px){.brand-wordmark{display:none}.rail .brand{margin-bottom:16px}.rail .brand-image{width:44px;height:44px}}\n.review-page section,.review-page svg,.review-page .notice{background:#000000;border-color:#242424}\n.select-option[aria-selected=true]{box-shadow:inset 2px 0 0 #ededed;font-weight:650}.select-option:focus-visible{outline:1px solid #ddd;outline-offset:-2px}.select-option:hover{text-decoration:underline;text-underline-offset:3px}\n";
export const capitalUiJs="(()=>{\n const money=n=>Number.isFinite(n)?'₹ '+n.toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2}):'—',esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n function render(prefix,days){const body=document.getElementById(prefix+'-margin-days'),svg=document.getElementById(prefix+'-margin-chart'),budgetInput=document.getElementById(prefix+'-cash-budget');if(!body)return;const budget=Number(budgetInput?.value),validBudget=Number.isFinite(budget)&&budget>=0;body.innerHTML=days.map(d=>{const estimate=d.dhan?.checkedSymbols?Math.max(d.fiveX?.withRealizedLossAndCostBuffer??0,d.dhan?.withRealizedLossAndCostBuffer??0):d.fiveX?.withRealizedLossAndCostBuffer,shortfall=validBudget&&Number.isFinite(estimate)?Math.max(0,estimate-budget):null;return `<tr><td>${esc(d.session)}<small>${d.entries} trades${d.unknownRelease?' · '+d.unknownRelease+' unknown releases':''}${d.excludedPositions?' · '+d.excludedPositions+' MCX excluded':''}</small></td><td>${money(d.peakPurchaseValue)}</td><td>${money(d.fiveX?.peakMargin)}</td><td>${money(estimate)}<small>Costs + known realized-loss buffer</small></td><td>${money(d.dhan?.peakRateIllustration)}<small>${d.dhan?.checkedSymbols||0}/${d.dhan?.totalSymbols||0} stocks checked${d.dhan?.checkedSymbols&&!d.dhan.complete?' · rest at 1×':''}${d.dhan?.checkedSymbols?' · +cost/loss buffer '+money(d.dhan.withRealizedLossAndCostBuffer):''}</small></td><td class=\"${shortfall>0?'negative':'positive'}\">${shortfall===null?'—':shortfall>0?money(shortfall)+' short':'Within illustration'}<small>${d.dhan?.checkedSymbols?'Dhan-rate / 1× fallback estimate':'Uniform 5× illustration'} against entered cash</small></td></tr>`;}).join('')||'<tr><td colspan=\"6\" class=\"capital-empty\">No entered equity trades in this period.</td></tr>';\n  const rates=days.flatMap(d=>(d.dhan?.rows||[]).filter(r=>r.status).map(r=>({...r,session:d.session})));document.getElementById(prefix+'-margin-rates').innerHTML=rates.length?'<table><thead><tr><th>SESSION</th><th>STOCK</th><th>DHAN LEVERAGE</th><th>REFERENCE PRICE / QTY</th><th>CHECKED / IST</th></tr></thead><tbody>'+rates.map(r=>'<tr><td>'+esc(r.session)+'</td><td>'+esc(r.symbol)+'</td><td>'+esc(r.status==='available'?(r.reportedLeverage??1/r.rate)+'×':r.error||'Unavailable')+'</td><td>'+money(r.referencePrice)+' / '+esc(r.quantity??'—')+'</td><td>'+esc(r.checkedAt?new Date(r.checkedAt).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}):'—')+'</td></tr>').join('')+'</tbody></table>':'<p class=\"panel-body muted\">No same-session Dhan snapshot was captured for these dates. Later rates are never substituted into historical sessions.</p>';\n  const peak=Math.max(1,...days.map(d=>d.peakPurchaseValue)),width=850/Math.max(1,days.length);let out='';for(let i=0;i<4;i++){const v=peak*i/3,y=180-v/peak*145;out+=`<path d=\"M65 ${y}H965\" stroke=\"#333\"/><text x=\"4\" y=\"${y+4}\" fill=\"#aaa\" font-size=\"10\">${Math.round(v).toLocaleString('en-IN')}</text>`;}days.forEach((d,i)=>{const x=85+i*width,w=Math.max(3,Math.min(32,width*.3)),y=180-d.peakPurchaseValue/peak*145,y5=180-(d.fiveX?.peakMargin??0)/peak*145;out+=`<rect x=\"${x}\" y=\"${y}\" width=\"${w}\" height=\"${180-y}\" fill=\"#6e6e6e\"><title>${esc(d.session)} full purchase value ${money(d.peakPurchaseValue)}</title></rect><rect x=\"${x+w+4}\" y=\"${y5}\" width=\"${w}\" height=\"${180-y5}\" fill=\"#e0e0e0\"><title>${esc(d.session)} 5× margin illustration ${money(d.fiveX?.peakMargin)}</title></rect>`;if(days.length<=14||i%Math.ceil(days.length/14)===0)out+=`<text x=\"${x+w}\" y=\"207\" text-anchor=\"middle\" fill=\"#aaa\" font-size=\"10\">${esc(d.session.slice(5))}</text>`;});svg.innerHTML=out;\n  const max=Math.max(0,...days.map(d=>d.fiveX?.withRealizedLossAndCostBuffer??0));document.getElementById(prefix+'-margin-max').textContent=days.length?money(max):'—';document.getElementById(prefix+'-margin-note').textContent='Highest daily 5× illustration with known costs and realized-loss buffer across '+days.length+' recorded dates. This is not summed across days. Same-session Dhan checks are indicative rates applied to entry values; unchecked stocks use 1× in the Dhan column. Historical missing paths remain unknown.';\n }\n window.NseCapital={render};\n})();\n";
export const capitalUiCss=".margin-panel{margin:22px 0}.margin-heading{padding:20px;display:flex;justify-content:space-between;gap:20px;align-items:center;flex-wrap:wrap}.margin-heading small{font-size:10px;letter-spacing:1px}.margin-heading strong{display:block;font:28px ui-monospace,monospace;margin-top:10px;color:#f2f2f2}.margin-heading label{display:grid;gap:6px;font-size:11px;color:#bbb}.margin-heading input{width:170px}.margin-chart-wrap{padding:0 20px 10px;background:#000000}.margin-chart-wrap svg{display:block;width:100%;max-height:260px}.margin-legend{display:flex;gap:25px;font-size:11px;color:#bdbdbd}.margin-panel .table-scroll{overflow:auto}.margin-panel table{min-width:950px}.margin-panel td{vertical-align:top;font-size:12px;white-space:nowrap}.margin-panel td small{display:block;font-size:10px;white-space:normal;max-width:200px;margin-top:7px}.margin-panel .panel-foot{font-size:11px;line-height:1.8}.margin-panel .panel-foot a{text-decoration:underline}.agent-page .margin-panel td:nth-child(4){min-width:150px}.capital-empty{text-align:center;padding:25px!important}@media(max-width:700px){.margin-heading{padding:15px}.margin-heading strong{font-size:23px}.margin-chart-wrap{padding:0 10px}.margin-legend{font-size:10px;gap:12px}}\n.margin-scope{padding:15px 20px 0;display:flex;gap:8px;align-items:center;flex-wrap:wrap}.margin-scope button{font-size:11px}.margin-scope button[aria-pressed=true]{background:#000000;border-color:#888}.margin-scope p{font-size:11px;color:#bbb;flex:1;min-width:200px}\n.margin-rate-details{margin:16px 20px;padding:12px;border:1px solid #333;border-radius:6px}.margin-rate-details summary{cursor:pointer;color:#ddd;font-size:12px}.margin-rate-details .table-scroll{margin-top:14px}\n";
